// Package: Azure.Storage.Queues
// Install: dotnet add package Azure.Storage.Queues

using Azure.Storage.Queues;
using Azure.Storage.Queues.Models;

public class QueueStorageService
{
    private readonly QueueClient _queue;

    public QueueStorageService(string connectionString, string queueName = "email-jobs")
    {
        var serviceUri = new Uri($"https://demostorageaccount.queue.core.windows.net/{queueName}");
        _queue = new QueueClient(serviceUri, new DefaultAzureCredential());
    }

    public async Task EnqueueAsync(string message, CancellationToken ct = default)
    {
        try
        {
            await _queue.CreateIfNotExistsAsync(cancellationToken: ct);
            await _queue.SendMessageAsync(message, cancellationToken: ct);
            Console.WriteLine($"Enqueued: {message}");
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Enqueue failed: {ex.Message}");
            throw;
        }
    }

    public async Task ProcessMessagesAsync(int maxMessages = 10, CancellationToken ct = default)
    {
        try
        {
            QueueMessage[] messages = await _queue.ReceiveMessagesAsync(maxMessages, cancellationToken: ct);
            foreach (var message in messages)
            {
                Console.WriteLine($"Process: {message.MessageText}");
                await _queue.DeleteMessageAsync(message.MessageId, message.PopReceipt, ct);
            }
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Receive failed: {ex.Message}");
            throw;
        }
    }
}

// Usage with sample data
var service = new QueueStorageService("DefaultEndpointsProtocol=https;AccountName=demostorageaccount;...");
await service.EnqueueAsync("order-1234");
await service.ProcessMessagesAsync();

// Expected output:
// Enqueued: order-1234
// Process: order-1234

