using Azure.Storage.Queues;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

public class QueueWorker : BackgroundService
{
    private readonly QueueClient _queue;
    private readonly ILogger<QueueWorker> _logger;

    public QueueWorker(QueueClient queue, ILogger<QueueWorker> logger)
    {
        _queue = queue;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        _logger.LogInformation("Queue worker started");

        while (!stoppingToken.IsCancellationRequested)
        {
            try
            {
                var messages = await _queue.ReceiveMessagesAsync(maxMessages: 1, cancellationToken: stoppingToken);
                foreach (var message in messages.Value)
                {
                    _logger.LogInformation("Processing: {MessageText}", message.MessageText);
                    // TODO: send email, generate PDF, etc.
                    await _queue.DeleteMessageAsync(message.MessageId, message.PopReceipt, stoppingToken);
                }
            }
            catch (RequestFailedException ex)
            {
                _logger.LogError(ex, "Queue processing error");
            }

            await Task.Delay(1000, stoppingToken);
        }
    }
}

